// Maximum likelihood fits against scipy.stats (test/fixtures/fit.json,
// generated by scripts/make_fit_reference.py).
import { describe, test, expect } from 'vitest'
import { readFileSync } from 'node:fs'
import { stats, seed, poisson, geometric, binomial, negativeBinomial, bernoulli } from '../index.js'

const { cases } = JSON.parse(readFileSync(new URL('./fixtures/fit.json', import.meta.url), 'utf8'))

const loglik = (d, xs) => xs.reduce((s, x) => s + d.logpdf(x), 0)
// the MLE of these families sits on the edge of the support: scipy's rounded estimates can fall
// just inside the data (likelihood -Infinity), so they are compared by parameters only
const BOUNDARY = new Set(['uniform', 'pareto'])

describe('fit matches scipy.stats', () => {
    test.each(cases.filter((c) => !BOUNDARY.has(c.family)).map((c) => [c.family, c]))('%s', (family, { data, params, exact }) => {
        const fitted = stats[family].fit(data)
        const reference = stats[family](...params)
        if (exact) {
            // closed forms and Newton iterations: same estimates as scipy to ~1e-7 (scipy's own
            // optimiser tolerance), and never a worse likelihood
            const ours = loglik(fitted, data)
            const theirs = loglik(reference, data)
            expect(ours).toBeGreaterThanOrEqual(theirs - 1e-9 * Math.abs(theirs))
            expect(Math.abs(ours - theirs)).toBeLessThan(1e-6 * Math.abs(theirs))
        } else {
            // scipy optimises numerically with a loose tolerance: the fit must be at least as
            // likely as scipy's, and close to it
            const ours = loglik(fitted, data)
            const theirs = loglik(reference, data)
            expect(ours).toBeGreaterThanOrEqual(theirs - 1e-9 * Math.abs(theirs))
            expect(ours - theirs).toBeLessThan(1e-3 * Math.abs(theirs))
        }
    })

    test('closed-form and Newton estimates agree with scipy parameter by parameter', () => {
        for (const { family, data, params } of cases.filter((c) => c.exact)) {
            const d = stats[family].fit(data)
            const reference = stats[family](...params)
            const keys = Object.keys(reference).filter((k) => typeof reference[k] === 'number')
            // scipy fits the Weibull shape numerically and stops ~1e-5 from the root of the score
            // equation, which randlibjs solves to rounding (its likelihood is higher, see above)
            const tol = family === 'weibull' ? 1e-4 : 1e-5
            for (const k of keys) {
                expect(Math.abs(d[k] - reference[k]), `${family}.${k}`).toBeLessThanOrEqual(tol * Math.abs(reference[k]) + 1e-12)
            }
        }
    })
})

describe('discrete fits', () => {
    test('closed-form estimates', () => {
        seed(4)
        expect(stats.poisson.fit([1, 2, 3, 6]).lambda).toBe(3)
        expect(stats.geometric.fit([1, 1, 2, 4]).p).toBe(0.5)
        expect(stats.bernoulli.fit([0, 1, 1, 1]).p).toBe(0.75)
        expect(stats.binomial.fit([2, 4, 6], { n: 10 }).p).toBeCloseTo(0.4, 15)
        expect(stats.negativeBinomial.fit([1, 3, 5], { n: 3 }).p).toBeCloseTo(0.5, 15)
        expect(stats.poisson.fit(poisson(7, 50000)).lambda).toBeCloseTo(7, 1)
        expect(stats.geometric.fit(geometric(0.2, 50000)).p).toBeCloseTo(0.2, 2)
        expect(stats.binomial.fit(binomial(30, 0.6, 50000), { n: 30 }).p).toBeCloseTo(0.6, 2)
        expect(stats.negativeBinomial.fit(negativeBinomial(4, 0.3, 50000), { n: 4 }).p).toBeCloseTo(0.3, 2)
        expect(stats.bernoulli.fit(bernoulli(0.1, 50000)).p).toBeCloseTo(0.1, 2)
    })
})

describe('fit input handling', () => {
    test('typed arrays are accepted', () => {
        const d = stats.normal.fit(new Float64Array([1, 2, 3, 4]))
        expect(d.loc).toBe(2.5)
    })

    test('clear errors', () => {
        expect(() => stats.normal.fit([1])).toThrow(/at least 2/)
        expect(() => stats.normal.fit([1, NaN])).toThrow(/finite/)
        expect(() => stats.normal.fit([2, 2, 2])).toThrow(/not all equal/)
        expect(() => stats.gamma.fit([1, -2, 3])).toThrow(/positive/)
        expect(() => stats.beta.fit([0.2, 1])).toThrow(/\(0, 1\)/)
        expect(() => stats.binomial.fit([1, 2])).toThrow(/number of trials/)
        expect(() => stats.binomial.fit([1, 12], { n: 10 })).toThrow(/<= n/)
        expect(() => stats.poisson.fit([1.5, 2])).toThrow(/integer/)
        expect(() => stats.normal.fit('abc')).toThrow(/array/)
        expect(stats.f.fit).toBeUndefined()
    })

    test('aliases share the fit', () => {
        const xs = [0.5, 1.2, 2.2, 3.1, 0.9]
        expect(stats.norm.fit(xs)).toEqual(stats.normal.fit(xs))
        expect(stats.chi2.fit(xs)).toEqual(stats.chisquare.fit(xs))
        expect(stats.t.fit([1, 2, 4, 8, 3, 2])).toEqual(stats.studentT.fit([1, 2, 4, 8, 3, 2]))
    })
})
